import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = null;int t = Integer.parseInt(br.readLine().trim());StringBuilder sb = new StringBuilder();for (int tc = 0; tc < t; tc++) {String s = br.readLine().trim();int count0 = 0;int count1 = 0;for (int i = 0; i < s.length(); i++) {if (s.charAt(i) == '0') {count0++;} else {count1++;}}int ans = s.length();for (int i = 0; i < s.length(); i++) {if (s.charAt(i) == '0') {if (count1 > 0) {count1--;ans--;} else {break;}} else {if (count0 > 0) {count0--;ans--;} else {break;}}}sb.append(ans).append("\n");}System.out.print(sb);}}